func:
// ── Validate payload ────────────────────────────────────────────────────
var p = msg.payload;
if (typeof p !== 'object' || p === null) {
    node.warn('cong1: invalid payload');
    return null;
}

var levelCm  = parseFloat(p.level_cm) || 0;
levelCm = Math.max(0, Math.min(180, levelCm));
var fillPct  = parseFloat(p.fill_pct) || ((levelCm / 180.0) * 100);
fillPct = Math.max(0, Math.min(100, fillPct));
var status   = p.status || 'green';

// ── Rate calculation with anti-spike protection ────────────────────────
var now = Date.now();
var prev = context.get('prev') || { level: levelCm, time: now, rate: 0.0 };
var dtSec = (now - prev.time) / 1000.0;

var calcRate = prev.rate;
if (dtSec >= 2.0) {
    var dtMin = dtSec / 60.0;
    calcRate = (levelCm - prev.level) / dtMin;
    calcRate = Math.max(-25.0, Math.min(25.0, calcRate));
    calcRate = Math.round(calcRate * 10) / 10;
    context.set('prev', { level: levelCm, time: now, rate: calcRate });
} else if (p.rise_rate !== undefined && !isNaN(parseFloat(p.rise_rate))) {
    calcRate = Math.max(-25.0, Math.min(25.0, parseFloat(p.rise_rate)));
    calcRate = Math.round(calcRate * 10) / 10;
}

// ── Store for downstream nodes & flow context ──────────────────────────
flow.set('cong1_level',   levelCm);
flow.set('cong1_fill',    fillPct);
flow.set('cong1_rate',    calcRate);
flow.set('cong1_status',  status);

// ── Build enriched payload ───────────────────────────────────────────────
msg.payload = {
    level_cm : Math.round(levelCm * 10) / 10,
    fill_pct : Math.round(fillPct * 10) / 10,
    rise_rate: calcRate,
    status   : status,
    timestamp: now
};

return msg;

var p       = msg.payload;
var levelCm = parseFloat(p.level_cm) || 0;
var fillPct = parseFloat(p.fill_pct) || 0;
var rate    = parseFloat(p.rise_rate) || 0;

// State: 0=green, 1=yellow, 2=red
var state   = flow.get('cong1_alert_state') || 0;

// Rate override → RED immediately if rapid rise > 5 cm/min
if (rate > 5) {
    state = 2;
} else {
    switch (state) {
        case 0: // GREEN
            if (fillPct >= 60) state = 1;
            break;
        case 1: // YELLOW
            if      (fillPct < 50) state = 0;
            else if (fillPct >= 80) state = 2;
            break;
        case 2: // RED
            if (fillPct < 70) state = 1;
            break;
    }
}

flow.set('cong1_alert_state', state);

var stateStr   = ['green','yellow','red'][state];
var stateVN    = ['AN TOÀN','CẢNH BÁO','NGUY HIỂM'][state];
var stateColor = ['#2ecc71','#f39c12','#e74c3c'][state];

p.alert_state  = state;
p.status       = stateStr;
p.status_vn    = stateVN;
p.state_color  = stateColor;

flow.set('cong1_status', stateStr);

// Output 1: Object for backend decisions & ThingSpeak
var msgData = { payload: p };

// Output 2: Pure number float for Gauge Fill %
var msgGauge = { payload: Math.round(fillPct * 10) / 10 };

// Output 3: Status string for UI text
var msgStatus = { payload: stateVN };

// Output 4: Rate string for UI text
var rateStr = (rate >= 0 ? '+' : '') + rate.toFixed(1) + ' cm/phút';
var msgRate = { payload: rateStr };

// Output 5: Data points for History Chart
var msgChartLevel = { topic: 'Mực nước (cm)', payload: Math.round(levelCm * 10) / 10 };
var msgChartFill  = { topic: 'Độ đầy (%)', payload: Math.round(fillPct * 10) / 10 };

return [msgData, msgGauge, msgStatus, msgRate, [msgChartLevel, msgChartFill]];

var p = msg.payload;
if (typeof p !== 'object' || p === null) {
    node.warn('duong1: invalid payload');
    return null;
}

var depthCm = parseFloat(p.depth_cm) || 0;
depthCm = Math.max(0, Math.min(100, depthCm));
var status  = p.status || 'green';

flow.set('duong1_depth',  depthCm);
flow.set('duong1_status', status);

msg.payload = {
    depth_cm : Math.round(depthCm * 10) / 10,
    status   : status,
    timestamp: Date.now()
};

return msg;

var p     = msg.payload;
var depth = parseFloat(p.depth_cm) || 0;

var state = flow.get('duong1_alert_state') || 0;

switch (state) {
    case 0: // GREEN
        if (depth >= 5)  state = 1;
        break;
    case 1: // YELLOW
        if      (depth < 3)  state = 0;
        else if (depth >= 15) state = 2;
        break;
    case 2: // RED
        if (depth < 10) state = 1;
        break;
}

flow.set('duong1_alert_state', state);

var stateStr   = ['green','yellow','red'][state];
var stateVN    = ['AN TOÀN','CẢNH BÁO','NGẬP'][state];
var stateColor = ['#2ecc71','#f39c12','#e74c3c'][state];

p.alert_state = state;
p.status      = stateStr;
p.status_vn   = stateVN;
p.state_color = stateColor;

flow.set('duong1_status', stateStr);

// Output 1: Object for combined alert & ThingSpeak
var msgData = { payload: p };

// Output 2: Pure number float for Gauge Depth cm
var msgGauge = { payload: Math.round(depth * 10) / 10 };

// Output 3: Status string for UI text
var msgStatus = { payload: stateVN };

// Output 4: Data point for History Chart
var msgChart = { topic: 'Độ sâu ngập (cm)', payload: Math.round(depth * 10) / 10 };

return [msgData, msgGauge, msgStatus, msgChart];

var cong1Status  = flow.get('cong1_status')  || 'green';
var duong1Status = flow.get('duong1_status') || 'green';
var fillPct  = flow.get('cong1_fill')   || 0;
var riseRate = flow.get('cong1_rate')   || 0;
var depthCm  = flow.get('duong1_depth') || 0;

var combinedLevel = 0; // 0=ok, 1=warning, 2=danger, 3=critical
var combinedText  = '';
var combinedColor = '#2ecc71';
var telegramMsg   = null;

if (cong1Status === 'red' && duong1Status === 'red') {
    combinedLevel = 3;
    combinedText  = '🆘 NGẬP NGHIÊM TRỌNG';
    combinedColor = '#8e44ad';
    telegramMsg   = '🆘 NGẬP NGHIÊM TRỌNG: Cống tràn + mặt đường ngập ' + depthCm + ' cm. KHẨN CẤP!';
} else if (duong1Status === 'red') {
    combinedLevel = 2;
    combinedText  = '🌊 NGẬP ĐƯỜNG';
    combinedColor = '#e74c3c';
    telegramMsg   = '🌊 NGẬP ĐƯỜNG: Độ sâu ngập ' + depthCm + ' cm. Yêu cầu điều tiết giao thông và bơm nước!';
} else if (cong1Status === 'red') {
    combinedLevel = 2;
    combinedText  = '🚨 NGUY HIỂM: CỐNG SẮP TRÀN';
    combinedColor = '#e74c3c';
    telegramMsg   = '🚨 NGUY HIỂM: Cống sắp tràn! Mực nước ' + fillPct + '%, dâng ' + riseRate + ' cm/phút. Yêu cầu bật bơm/mở van ngay!';
} else if (cong1Status === 'yellow' || duong1Status === 'yellow') {
    combinedLevel = 1;
    combinedText  = '⚠️ CẢNH BÁO';
    combinedColor = '#f39c12';
    if (cong1Status === 'yellow') {
        telegramMsg = '⚠️ CẢNH BÁO: Mực nước trong cống đạt ' + fillPct + '%, tốc độ dâng ' + riseRate + ' cm/phút. Đề nghị theo dõi.';
    }
} else {
    combinedText  = '✅ AN TOÀN';
    combinedColor = '#2ecc71';
}

// Telegram rate limiting — only send on state change
var prevCombined = flow.get('prev_combined_level');
var shouldTelegram = (telegramMsg !== null) &&
                     (combinedLevel !== prevCombined) &&
                     (combinedLevel >= 1);
flow.set('prev_combined_level', combinedLevel);

var outMsg = {
    payload: {
        combined_level : combinedLevel,
        combined_text  : combinedText,
        combined_color : combinedColor,
        cong1_status   : cong1Status,
        duong1_status  : duong1Status,
        fill_pct       : fillPct,
        rise_rate      : riseRate,
        depth_cm       : depthCm,
        timestamp      : Date.now()
    }
};

var telegramOut = shouldTelegram ? { payload: { chatId: global.get('telegram_chat_id') || 0, type: 'message', content: telegramMsg } } : null;

return [outMsg, telegramOut];

if (!msg || !msg.payload) return null;

// msg.payload is already { chatId, type, content } from combined alert
var chatId = msg.payload.chatId;
if (!chatId || chatId === 0) {
    node.warn('Telegram chatId not set. Set global.telegram_chat_id.');
    return null;
}

return msg;

var p     = msg.payload;
var apiKey= global.get('thingspeak_write_key') || 'YOUR_API_KEY';
var state = p.alert_state || 0;

msg.url    = 'https://api.thingspeak.com/update';
msg.method = 'POST';
msg.headers= { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload= 'api_key=' + apiKey +
             '&field1=' + (p.level_cm  || 0) +
             '&field2=' + (p.fill_pct  || 0) +
             '&field3=' + (p.rise_rate || 0) +
             '&field5=' + state;

// Mark as cong1 source so the merge node knows
msg._source = 'cong1';

return msg;

var p     = msg.payload;
var apiKey= global.get('thingspeak_write_key') || 'YOUR_API_KEY';
var state = p.alert_state || 0;

msg.url    = 'https://api.thingspeak.com/update';
msg.method = 'POST';
msg.headers= { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload= 'api_key=' + apiKey +
             '&field4=' + (p.depth_cm || 0) +
             '&field6=' + state;

msg._source = 'duong1';
return msg;

// ThingSpeak free tier: max 1 update per 15 seconds
var lastSend = context.get('lastSend') || 0;
var now = Date.now();
if (now - lastSend < 15000) {
    // Store pending but skip sending
    context.set('pending', msg);
    return null;
}
context.set('lastSend', now);
return msg;

var status = msg.payload === 'online' ? '🟢 ONLINE' : '🔴 OFFLINE';
msg.payload = status;
flow.set('cong1_online', msg.payload);
return msg;

var status = msg.payload === 'online' ? '🟢 ONLINE' : '🔴 OFFLINE';
msg.payload = status;
flow.set('duong1_online', msg.payload);
return msg;

// ─── Set credentials or get from environment ──────────────
global.set('telegram_chat_id',    env.get('TELEGRAM_CHAT_ID')    || 0);
global.set('thingspeak_write_key', env.get('THINGSPEAK_WRITE_API_KEY') || 'YOUR_KEY');

node.status({ fill:'green', shape:'dot', text:'Globals initialised' });
return null;

var p = msg.payload;
if (!p) return null;

// Output 1: Gauge dự báo mực nước 5m (pure number)
var msgGauge5m = {
    payload: p.predicted_level_5m,
    topic: 'Dự báo +5m'
};

// Output 2: Gauge xác suất ngập 30m (%) (pure number)
var msgGauge30m = {
    payload: p.prob_flood_30m,
    topic: 'Xác suất ngập +30m (%)'
};

// Output 3: Trạng thái đa tầng (Object for UI Template)
var msgStatus = {
    payload: {
        status_color: p.status_color || '#2ecc71',
        predicted_status: p.predicted_status || 'AN TOÀN',
        predicted_fill_5m: p.predicted_fill_5m || 0,
        status_30m_color: p.status_30m_color || '#2ecc71',
        status_30m: p.status_30m || 'AN TOÀN THOÁT NƯỚC',
        prob_flood_30m: p.prob_flood_30m || 0,
        current_level: p.current_level || 0,
        predicted_level_15m: p.predicted_level_15m || 0,
        predicted_level_30m: p.predicted_level_30m || 0,
        predicted_level_60m: p.predicted_level_60m || 0
    }
};

// Output 4: Khuyến nghị điều phối giao thông (Object for UI Template)
var warnColor = p.early_warning ? '#e74c3c' : (p.prob_flood_30m >= 50 ? '#f39c12' : '#2ecc71');
var msgTraffic = {
    payload: {
        traffic_color: warnColor,
        traffic_advisory: p.traffic_advisory || 'Lưu lượng thoát ổn định.'
    }
};

// Output 5: Biểu đồ đa đường (Actual, +5m, +30m, +60m)
var msgChartActual = { topic: '1. Mực nước thực tế (cm)', payload: p.current_level };
var msgChart5m     = { topic: '2. Dự báo AI +5m (cm)',   payload: p.predicted_level_5m };
var msgChart30m    = { topic: '3. Dự báo AI +30m (cm)',  payload: p.predicted_level_30m };
var msgChart60m    = { topic: '4. Dự báo AI +60m (cm)',  payload: p.predicted_level_60m };

// Output 6: Telegram early warning alert
var msgTg = null;
if (p.early_warning) {
    var lastAlert = flow.get('last_ai_alert_time') || 0;
    var now = Date.now();
    if (now - lastAlert > 180000) {
        flow.set('last_ai_alert_time', now);
        var tgChatId = global.get('telegram_chat_id');
        msgTg = {
            payload: {
                chatId: tgChatId,
                type: 'message',
                content: '🚨 *CẢNH BÁO SỚM ĐIỀU PHỐI GIAO THÔNG (AI MULTI-HORIZON)*\n\n' +
                         '📍 *Vị trí:* Cống 1 & Điểm trũng mặt đường\n' +
                         '🌊 *Mực nước hiện tại:* ' + p.current_level + ' cm (' + p.current_fill + '%)\n' +
                         '🔮 *Dự báo +5 phút:* ' + p.predicted_level_5m + ' cm\n' +
                         '🔮 *Dự báo +30 phút:* ' + p.predicted_level_30m + ' cm (*Xác suất ngập: ' + p.prob_flood_30m + '%*)\n' +
                         '🔮 *Dự báo +60 phút:* ' + p.predicted_level_60m + ' cm\n\n' +
                         '📢 *Khuyến nghị:* ' + p.traffic_advisory + '\n\n' +
                         '_(Tích hợp Radar Nowcasting & Cảm biến IoT UET)_'
            }
        };
    }
}

return [msgGauge5m, msgGauge30m, msgStatus, msgTraffic, [msgChartActual, msgChart5m, msgChart30m, msgChart60m], msgTg];
